/* defs.h for the Helios (transputer) build of Frotz, written by hand
 * instead of generated by the Unix Makefile (see Makefile.helios). */
#ifndef COMMON_DEFINES_H
#define COMMON_DEFINES_H
#define RELEASE_NOTES "Helios port."
#ifndef HELIOS_PORT
#define HELIOS_PORT
#endif
#define NO_BLORB
#define NO_SOUND
#define NO_STRDUP
#define NO_STRNDUP
#define NO_BASENAME
#define MAX_UNDO_SLOTS 25
#define MAX_FILE_NAME 80
#define TEXT_BUFFER_SIZE 512
#define INPUT_BUFFER_SIZE 200
#define STACK_SIZE 1024
/* Helios stdio.h has no FILENAME_MAX; limits.h has PATH_MAX only for
 * POSIX sources. */
#define PATH_MAX 512
#define FILENAME_MAX 256
/* What the Helios C library lacks (src/helios/hcompat.c). */
#include <stdarg.h>
typedef int sig_atomic_t;
typedef int ssize_t;
#include <stddef.h>
int hc_vsnprintf(char *buf, size_t size, const char *fmt, va_list ap);
int hc_snprintf(char *buf, size_t size, const char *fmt, ...);
#define vsnprintf hc_vsnprintf
char *hc_dirname(char *path);
#define dirname hc_dirname
#ifndef true
#define true 1
#define false 0
#endif
#define snprintf hc_snprintf
#endif /* COMMON_DEFINES_H */
